117	impl<T: Tun, B: UDP> WireGuard<T, B> {
118	    /// Brings the WireGuard device down.
119	    /// Usually called when the associated interface is brought down.
120	    ///
121	    /// This stops any further action/timer on any peer
122	    /// and prevents transmission of further messages,
123	    /// however the device retrains its state.
124	    ///
125	    /// The instance will continue to consume and discard messages
126	    /// on both ends of the device.
127	    pub fn down(&self) {
128	        // ensure exclusive access (to avoid race with "up" call)
129	        let mut enabled = self.enabled.write();
130	
131	        // check if already down
132	        if !(*enabled) {
133	            return;
134	        }
135	
136	        // set mtu
137	        self.mtu.store(0, Ordering::Relaxed);
138	
139	        // avoid transmission from router
140	        self.router.down();
141	
142	        // set all peers down (stops timers)
143	        for (_, peer) in self.peers.write().iter() {
144	            peer.stop_timers();
145	            peer.down();
146	        }
147	
148	        *enabled = false;
149	    }
150	
151	    /// Brings the WireGuard device up.
152	    /// Usually called when the associated interface is brought up.
153	    pub fn up(&self, mtu: usize) {
154	        // ensure exclusive access (to avoid race with "up" call)
155	        let mut enabled = self.enabled.write();
