        fn readline<R: Read>(reader: &mut R) -> Result<String, ConfigError> {
            let mut m: [u8; 1] = [0u8];
            let mut l: String = String::with_capacity(MAX_LINE_LENGTH);
            while reader.read_exact(&mut m).is_ok() {
                let c = m[0] as char;
                if c == '\n' {
                    log::trace!("UAPI, line: {}", l);
                    return Ok(l);
                };
